UPDATE 
	CARE_LIST 
SET 
	CL_FAVORITES = #{cl_favorites} 
WHERE 
	CL_NO = #{cl_no}

mapper.select:
SELECT CL.*, CLC.*, CPD.*, D.*, DC.* FROM CARE_LIST AS CL LEFT JOIN CARE_LIST_CATEGORY AS CLC ON CL.CL_CATEGORY_NO = CLC.CLC_NO AND CLC.CLC_IS_DELETED = 1 LEFT JOIN CARE_PERSON_DISEASE AS CPD ON CL.CL_NO = CPD.CPD_CARE_LIST_NO LEFT JOIN DISEASE AS D ON CPD.CPD_DISEASE_NO = D.D_NO LEFT JOIN DISEASE_CATEGORY AS DC ON D.D_CATEGORY_NO = DC.DC_NO WHERE CL.CL_IS_DELETED = 1 AND CL.CL_USER_NO = #{u_no}
AND CL.CL_CATEGORY_NO = #{infoNo}
AND CL.CL_FAVORITES = 1
AND (CL.CL_CATEGORY_NO IS NULL OR CL.CL_CATEGORY_NO >= 0)
ORDER BY CL.${sortValue} ${order} LIMIT #{start}, #{limit}

SELECT CL.*, CLC.*, CPD.*, D.*, DC.* FROM CARE_LIST AS CL LEFT JOIN CARE_LIST_CATEGORY AS CLC ON CL.CL_CATEGORY_NO = CLC.CLC_NO AND CLC.CLC_IS_DELETED = 1 LEFT JOIN CARE_PERSON_DISEASE AS CPD ON CL.CL_NO = CPD.CPD_CARE_LIST_NO LEFT JOIN DISEASE AS D ON CPD.CPD_DISEASE_NO = D.D_NO LEFT JOIN DISEASE_CATEGORY AS DC ON D.D_CATEGORY_NO = DC.DC_NO WHERE CL.CL_IS_DELETED = 1 AND CL.CL_USER_NO = #{u_no}
AND CL.CL_CATEGORY_NO = #{infoNo}
AND CL.CL_FAVORITES = 1
AND (CL.CL_CATEGORY_NO IS NULL OR CL.CL_CATEGORY_NO >= 0)
ORDER BY CL.${sortValue} ${order}

SELECT COUNT(*) FROM CARE_LIST AS CL LEFT JOIN CARE_LIST_CATEGORY AS CLC ON CL.CL_CATEGORY_NO = CLC.CLC_NO AND CLC.CLC_IS_DELETED = 1 WHERE CL.CL_IS_DELETED = 1 AND CL.CL_USER_NO = #{u_no}
AND CL.CL_CATEGORY_NO = #{infoNo}
AND CL.CL_FAVORITES = 1

